const Check = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="#06B6D4" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
    <path d="M20 6L9 17l-5-5" />
  </svg>
);

const CHECKLIST = [
  'Audits your website',
  'Finds technical and content issues',
  'Applies supported fixes automatically',
  'Helps improve AI and search visibility',
  'Builds your social content calendar',
  'Publishes across connected channels',
];

const STATS = [
  ['Audits run', 'Daily'],
  ['Engines tracked', '6'],
  ['Channels automated', '5'],
  ['Marketing hires needed', '0'],
];

export default function Agent() {
  return (
    <section className="dark">
      <div className="wrap agent-grid">
        <div>
          <span className="eyebrow">Your AI growth agent</span>
          <h2 style={{ color: 'var(--white)', fontSize: 'clamp(24px,3vw,32px)', marginTop: 14 }}>
            One AI agent that audits, fixes, ranks and posts — so you don't need a marketing hire.
          </h2>
          <p style={{ color: 'rgba(255,255,255,0.68)', marginTop: 16, fontSize: 15 }}>
            The AI agent learns your brand and priorities and helps manage your marketing work.
          </p>
          <ul className="checklist" style={{ marginTop: 28 }}>
            {CHECKLIST.map((text) => (
              <li key={text}>
                <span className="tick"><Check /></span>
                <p>{text}</p>
              </li>
            ))}
          </ul>
          <p style={{ color: 'rgba(255,255,255,0.68)', marginTop: 24, fontSize: 15 }}>
            This keeps your audit, content, and publishing work connected in one place.
          </p>
        </div>
        <div className="agent-panel">
          {STATS.map(([label, value]) => (
            <div className="row" key={label}><span>{label}</span><span>{value}</span></div>
          ))}
        </div>
      </div>
    </section>
  );
}
